VOL_EXP = 0.6       # inverse-vol exponent (v5: 0.5 -> 0.6)
STALE_N = 5         # consecutive identical closes => stale quote
# v27 defensive multipliers (fired 2029-04-09 after the 03-26..04-09 block +1.35%):
