DEFENSIVE_MULT = {
    "XAU": 0.85, "US10Y": 0.70, "CN10Y": 0.70,   # safe havens (v39 fired 2031-06-30: XAU x1.00->x0.85 2nd cons neg -4.34%/-1.01%; US10Y x0.60->x0.70 RE-BOOST 2 cons pos +0.80%/+4.74%; CN10Y kept x0.70 frozen stale)
